insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('69f4d401-317b-507b-b501-c0e872b07a43', 'curatela', 'Curatela / Capacidade Civil',
insert into public.secoes (id, tipo_laudo_id, codigo, titulo, ordem, condicional, condicao, texto_automatico_template) values
  ('38082c22-b6ec-570d-972e-4274506336aa', '69f4d401-317b-507b-b501-c0e872b07a43', 'identificacao_perito', 'I — Identificação do(a) Perito(a) Judicial', 1, false, null, null),
  ('4c392dae-f4f7-5122-ab5a-eb38c0e26c03', '69f4d401-317b-507b-b501-c0e872b07a43', 'identificacao_periciando', 'II — Identificação do(a) Periciando(a)', 2, false, null, null),
  ('17dd4988-565a-55cd-9600-f3f38423148b', '69f4d401-317b-507b-b501-c0e872b07a43', 'presentes_fontes_informacao', 'III — Presentes ao Ato Pericial e Fontes de Informação', 3, false, null, null),
  ('615821e2-6df2-5113-a17a-c59dfbaf344b', '69f4d401-317b-507b-b501-c0e872b07a43', 'objeto_pericia', 'IV — Objeto da Perícia', 4, false, null, 'Sob a perspectiva médico-legal, objetiva-se avaliar a existência de condição clínica capaz de repercutir sobre a autonomia e a capacidade civil do(a) periciando(a), especialmente quanto à sua aptidão para compreender informações relevantes, avaliar consequências, deliberar, manifestar vontade e praticar autonomamente atos da vida civil, indicando-se, quando tecnicamente possível, os domínios eventualmente comprometidos e a necessidade de apoio de terceiros.'),
  ('f3c3fe51-0873-5b0c-a9e5-c98d952e8437', '69f4d401-317b-507b-b501-c0e872b07a43', 'metodologia_pericial', 'V — Metodologia Pericial', 5, false, null, 'A conclusão médico-pericial resulta da integração entre os dados documentais, clínicos, cognitivos, comportamentais e funcionais obtidos durante a avaliação, considerada sua pertinência ao objeto determinado pelo Juízo.'),
  ('df7868ed-f7bb-532f-9671-6ca115ea182a', '69f4d401-317b-507b-b501-c0e872b07a43', 'matriz_documentos_analisados', 'VI — Matriz dos Documentos Analisados', 6, false, null, 'Foram analisados {{total_documentos}} documentos, totalizando {{total_paginas}} páginas, compreendendo {{categorias_principais}}, considerados em conjunto com os achados obtidos durante o exame pericial.'),
  ('2b3ffd99-d5fc-5062-bc5c-e7ce04619a8d', '69f4d401-317b-507b-b501-c0e872b07a43', 'historia_clinica', 'VII — Reconstrução da História Clínica', 7, false, null, 'Conforme as informações obtidas, o(a) periciando(a) apresenta quadro de {{diagnostico_informado}}, com início {{inicio_condicao}}, evolução {{curso_clinico}} e manifestações predominantemente caracterizadas por {{manifestacoes_predominantes}}.'),
  ('2d4791fb-e27d-5fb4-ba71-573ca97ebcf1', '69f4d401-317b-507b-b501-c0e872b07a43', 'antecedentes_tratamentos', 'VIII — Antecedentes e Tratamentos', 8, false, null, null),
  ('27fbf857-417c-5198-894f-cb2b70abc9ea', '69f4d401-317b-507b-b501-c0e872b07a43', 'exame_clinico_geral', 'IX — Exame Clínico Geral', 9, false, null, 'Ao exame clínico geral, apresentou-se em estado geral {{estado_geral}}, com apresentação pessoal {{apresentacao_pessoal}}, higiene {{higiene}}, locomoção {{locomocao}} e comunicação {{comunicacao}}. Durante a avaliação mostrou-se {{cooperacao_exame}} às solicitações periciais.'),
  ('2c2d3d72-c0c3-5846-9f38-37978db3e408', '69f4d401-317b-507b-b501-c0e872b07a43', 'exame_estado_mental', 'X — Exame do Estado Mental', 10, false, null, 'Ao exame do estado mental, o(a) periciando(a) apresentou-se {{consciencia}}, com orientação autopsíquica {{orientacao_autopsiquica}}, temporal {{orientacao_temporal}}, espacial {{orientacao_espacial}} e situacional {{orientacao_situacional}}, atenção e concentração {{atencao_concentracao}}, memória imediata {{memoria_imediata}}, recente {{memoria_recente}} e remota {{memoria_remota}}, linguagem {{linguagem}} e pensamento com curso {{pensamento_curso}}, forma {{pensamento_forma}} e conteúdo {{pensamento_conteudo}}. O juízo crítico mostrou-se {{juizo_critico}}, o insight {{insight}}, observando-se funções executivas — planejamento {{funcao_executiva_planejamento}}, organização {{funcao_executiva_organizacao}}, resolução de problemas {{funcao_executiva_resolucao_problemas}} e flexibilidade cognitiva {{funcao_executiva_flexibilidade_cognitiva}} — e capacidade de abstração {{capacidade_abstracao}}.'),
  ('f3c251ab-d2ce-5696-89d4-06a3f15f8c9c', '69f4d401-317b-507b-b501-c0e872b07a43', 'avaliacao_cognitiva_complementar', 'XI — Avaliação Cognitiva Complementar', 11, false, null, 'Observação: o resultado de instrumento de rastreio cognitivo deverá ser interpretado em conjunto com escolaridade, contexto sociocultural, condições sensoriais, exame clínico e funcionalidade, não sendo utilizado isoladamente para definição de capacidade civil.'),
  ('647490b9-ed73-511f-8f3f-b6ca2a4dc76c', '69f4d401-317b-507b-b501-c0e872b07a43', 'avaliacao_funcionalidade', 'XII — Avaliação da Funcionalidade', 12, false, null, 'Quanto à funcionalidade, apresenta [funcionalidade_abvd_grau] para as atividades básicas da vida diária e [funcionalidade_aivd_grau] de dependência para as atividades instrumentais, necessitando de [funcionalidade_tipo_auxilio] principalmente para [funcionalidade_atividades_criticas].'),
  ('0188ba27-cec7-586d-97e6-2f4b67ae8af7', '69f4d401-317b-507b-b501-c0e872b07a43', 'avaliacao_capacidade_civil_discernimento', 'XIII — Avaliação Específica da Capacidade Civil e do Discernimento', 13, false, null, null),
  ('651f303d-e9d1-55b2-9357-f1d63e642bf8', '69f4d401-317b-507b-b501-c0e872b07a43', 'autonomia_vontade_apoio', 'XIV — Autonomia, Manifestação da Vontade e Necessidade de Apoio', 14, false, null, 'O(a) periciando(a) apresenta capacidade de manifestação da vontade {{manifestacao_vontade}}, com {{suscetibilidade_influencia_indevida}} de suscetibilidade à influência indevida e necessidade de {{necessidade_global_apoio}} para {{dominios_necessita_apoio}}.'),
  ('7fabc9e8-8e47-5e80-9095-8393626f935f', '69f4d401-317b-507b-b501-c0e872b07a43', 'diagnostico_prognostico', 'XV — Diagnóstico Médico-Pericial e Prognóstico', 15, false, null, null),
  ('ff1784c0-5149-5836-a94b-9bea1d7cd633', '69f4d401-317b-507b-b501-c0e872b07a43', 'discussao_medico_legal', 'XVI — Discussão Médico-Legal', 16, false, null, 'A existência de diagnóstico médico não determina, isoladamente, incapacidade civil. A análise médico-pericial deve estabelecer se as alterações clínicas identificadas repercutem concretamente sobre as capacidades necessárias à compreensão, deliberação, manifestação da vontade, autodeterminação e exercício dos atos da vida civil. No caso em análise, o(a) periciando(a) apresenta {{diagnostico_principal}}, caracterizado por [achados_clinicos_principais], observando-se ao exame [alteracoes_cognitivas_psiquicas_principais]. Do ponto de vista funcional, apresenta [grau_autonomia], necessitando de [grau_auxilio] para [atividades_dependentes]. Quanto à capacidade decisória, verifica-se [preservacao_comprometimento_capacidade_decisoria] da capacidade de compreender informações, avaliar consequências, comparar alternativas, manifestar escolhas e reconhecer riscos relacionados aos atos avaliados. A análise conjunta desses elementos permite estabelecer que [sintese_capacidade_civil]. A eventual indicação de curatela deve ser interpretada de maneira individualizada, proporcional às necessidades concretamente identificadas e com preservação máxima possível da autonomia e da manifestação de vontade do(a) periciando(a).'),
  ('e1923e6e-1a37-556a-9f74-bf042707f834', '69f4d401-317b-507b-b501-c0e872b07a43', 'respostas_quesitos', 'XVII — Respostas aos Quesitos', 17, false, null, null),
  ('da60ed75-515d-58cc-b49e-329695df54d1', '69f4d401-317b-507b-b501-c0e872b07a43', 'conclusao_medico_pericial', 'XVIII — Conclusão Médico-Pericial', 18, false, null, null),
  ('60a2b5cb-f4b3-5aec-9931-c6d2c2e5f917', '69f4d401-317b-507b-b501-c0e872b07a43', 'encerramento', 'XIX — Encerramento', 19, false, null, 'O presente laudo representa o entendimento técnico desta Perita Judicial, fundamentado nos elementos disponíveis e nos achados obtidos durante a avaliação médico-pericial, permanecendo esta profissional à disposição do Juízo para eventuais esclarecimentos que se façam necessários.');
