  ('4d18b3ae-374e-5544-9cd5-43073c2c3207', 'da60ed75-515d-58cc-b49e-329695df54d1', null, 'conclusao_modelo_automatico', 'Modelo automático de conclusão', 'selecao_unica', 10, false, true, '[{"codigo": "capacidade_preservada", "rotulo": "Capacidade preservada", "texto_automatico": "Diante dos elementos médico-periciais obtidos, não foram identificadas alterações clínicas, cognitivas ou funcionais de magnitude suficiente para comprometer significativamente a capacidade do(a) periciando(a) de compreender, deliberar e manifestar sua vontade em relação aos atos avaliados, não se evidenciando, sob a perspectiva médico-pericial, necessidade atual de representação ou assistência contínua para atos patrimoniais e negociais."}, {"codigo": "comprometimento_parcial_setorial", "rotulo": "Comprometimento parcial/setorial", "texto_automatico": "O(a) periciando(a) apresenta {{diagnostico_principal}}, com repercussão sobre [funcoes_comprometidas]. Mantém capacidade para [dominios_preservados], porém apresenta prejuízo relevante para [dominios_comprometidos], especialmente quanto a [atos_afetados]. Sob a perspectiva médico-pericial, necessita de apoio/assistência para esses atos específicos, devendo ser preservada sua autonomia nos demais domínios em que demonstra compreensão, discernimento e capacidade de manifestação da vontade."}, {"codigo": "comprometimento_acentuado", "rotulo": "Comprometimento acentuado", "texto_automatico": "O(a) periciando(a) apresenta {{diagnostico_principal}}, associado a comprometimento significativo de [funcoes_comprometidas], com repercussão relevante sobre a capacidade de compreender informações, avaliar consequências, deliberar e administrar autonomamente atos de natureza patrimonial e negocial. Sob a perspectiva médico-pericial, evidencia-se necessidade contínua de proteção e auxílio de terceiros nesses domínios, preservando-se, sempre que possível, sua participação nas decisões e a manifestação de suas preferências e vontade."}, {"codigo": "inconclusivo", "rotulo": "Inconclusivo", "texto_automatico": "Os elementos atualmente disponíveis não permitem estabelecer, com segurança médico-pericial suficiente, a extensão da repercussão da condição clínica sobre a capacidade civil do(a) periciando(a), sendo necessária complementação por [tipo_complementacao_necessaria] antes da emissão de conclusão definitiva."}]'::jsonb, null, false, null, true),
